create schema if not exists app_private;
revoke all on schema app_private from public;
grant usage on schema app_private to authenticated;
create table app_private.teachers(user_id uuid primary key references auth.users(id) on delete cascade);
create function app_private.is_teacher() returns boolean language sql stable security definer set search_path='' as $$ select auth.uid() is not null and exists(select 1 from app_private.teachers where user_id=auth.uid()) $$;
revoke all on function app_private.is_teacher() from public,anon;
grant execute on function app_private.is_teacher() to authenticated;
create table public.profiles(user_id uuid primary key references auth.users(id) on delete cascade, full_name text not null check(length(full_name) between 1 and 100), class_name text not null default '' check(length(class_name)<=60), school text not null default '' check(length(school)<=200), bio text not null default '' check(length(bio)<=1000));
create table public.planner(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,kind text not null check(kind in ('task','note','lesson')),title text not null check(length(title) between 1 and 200),body text not null default '' check(length(body)<=5000),date date,slot text not null default '' check(length(slot)<=100),done boolean not null default false,created_at timestamptz not null default now());
create index on public.planner(user_id);
create table public.posts(id uuid primary key default gen_random_uuid(),author_id uuid not null references auth.users(id),kind text not null check(kind in ('assignment','announcement','resource')),title text not null check(length(title) between 1 and 200),body text not null default '' check(length(body)<=5000),class_name text not null default '',due date,url text not null default '' check(length(url)<=2000),created_at timestamptz not null default now());
create index on public.posts(author_id);
create table public.completions(user_id uuid not null references auth.users(id) on delete cascade,post_id uuid not null references public.posts(id) on delete cascade,primary key(user_id,post_id));
create index on public.completions(post_id);
alter table public.profiles enable row level security;
alter table public.planner enable row level security;
alter table public.posts enable row level security;
alter table public.completions enable row level security;
create policy profile_read on public.profiles for select to authenticated using(user_id=(select auth.uid()));
create policy profile_insert on public.profiles for insert to authenticated with check(user_id=(select auth.uid()));
create policy profile_update on public.profiles for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy planner_owner on public.planner for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy posts_read on public.posts for select to authenticated using(true);
create policy posts_insert on public.posts for insert to authenticated with check(author_id=(select auth.uid()) and (select app_private.is_teacher()));
create policy posts_update on public.posts for update to authenticated using(author_id=(select auth.uid()) and (select app_private.is_teacher())) with check(author_id=(select auth.uid()) and (select app_private.is_teacher()));
create policy posts_delete on public.posts for delete to authenticated using(author_id=(select auth.uid()) and (select app_private.is_teacher()));
create policy completions_owner on public.completions for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
grant select,insert,update on public.profiles to authenticated;
grant select,insert,update,delete on public.planner,public.posts,public.completions to authenticated;
revoke all on public.profiles,public.planner,public.posts,public.completions from anon;
create function public.my_teacher_status() returns boolean language sql stable security invoker set search_path='' as $$select app_private.is_teacher()$$;
revoke all on function public.my_teacher_status() from public,anon;
grant execute on function public.my_teacher_status() to authenticated;

